var AUTO_CHEST_PER_RUN = (() => {
  const field = Object.values(CHESTS).filter((c) => c.id !== "radiant");
  const tot = field.reduce((a, c) => a + c.weight, 0);
  const k = CHEST_RULE.PER_WIN * (1 + CHEST_RULE.TRAP_P * CHEST_RULE.AUTO_MIMIC_WIN);
  const row = Object.fromEntries(field.map((c) => [c.id, c.weight / tot * k]));
  const rp = CHEST_RULE.RADIANT_P5 || 0;
  const row5 = { ...Object.fromEntries(field.map((c) => [c.id, c.weight / tot * k * (1 - rp)])), radiant: k * rp };
  return { 1: { ...row }, 2: { ...row }, 3: { ...row }, 4: { ...row }, 5: row5 };
})();
