  prop_58: { name: "\uAE30\uC2B5", power: 2, dmg: "phys", move: { kind: "leap", at: "weak", back: 3 }, desc: "<b>\uCCB4\uB825\uC774 \uAC00\uC7A5 \uB0AE\uC740 \uC801</b>\uC5D0\uAC8C \uB6F0\uC5B4\uB4E4\uC5B4 <b>\uACF5\uACA9\uB825\uC758 2.0\uBC30</b>\uC5D0 \uD574\uB2F9\uD558\uB294 \uBB3C\uB9AC \uD53C\uD574\uB97C \uC785\uD799\uB2C8\uB2E4. <b>3\uCD08 \uB4A4</b> \uC81C\uC790\uB9AC\uB85C \uB3CC\uC544\uC635\uB2C8\uB2E4." },
