var clampFlow = (v, def) => Math.max(def.floor ?? 0, Math.min(def.cap, v));
var STATFEED_K = 0.5;
function statPartOf(ch, def) {
  let v = def.base || 0;
  for (const [stat, k] of Object.entries(def.from || {})) v += (ch.stat?.[stat] || 0) * k;
  if (T.USE_STATFEED_V2 && def.fromPlan) {
    v += (def.basePlan || 0) * STATFEED_K;
    for (const [stat, k] of Object.entries(def.fromPlan)) v += (ch.stat?.[stat] || 0) * k * STATFEED_K;
  }
  return v;
}
var GEM_BASE = { on: true };
function gemBaseOf(ch) {
  const role = effClass(ch).role;
  const base2 = {};
  for (const [key, def] of Object.entries(FLOW)) {
    let v = statPartOf(ch, def);
    for (const g of ch.gear || []) v += gearFlow(g, role, { noGems: true })[key] || 0;
    v += ch.essence?.flow?.[key] || 0;
    base2[key] = v;
  }
  return base2;
}
function flowStatsOf(ch) {
  const out = {};
  const role = effClass(ch).role;
  const hasGem = GEM_BASE.on && (ch.gear || []).some((g) => (g.sockets || []).some(Boolean));
  const base2 = hasGem ? gemBaseOf(ch) : null;
  for (const [key, def] of Object.entries(FLOW)) {
    let v = statPartOf(ch, def);
    for (const g of ch.gear || []) v += gearFlow(g, role, { base: base2 })[key] || 0;
    v += ch.essence?.flow?.[key] || 0;
    out[key] = clampFlow(v, def);
  }
  return out;
}

