// src/game/damage.js
var NO_DAMAGE_STEPS = Object.freeze([]);
function computeDamage({ attacker: a, defender: d, skill = null, raw = 0, rng = Math.random, now = 0, trace = true }) {
  const steps = trace ? [] : NO_DAMAGE_STEPS;
  const out = { raw, final: 0, crit: false, blocked: false, dodged: false, immune: false, steps };
  if (T.USE_DMG_V2 && (d.immuneUntil || 0) > now) {
    out.immune = true;
    if (trace) steps.push({ key: "immune", name: "\uAC1C\uC804 \uBA74\uC5ED", mult: 0 });
    return out;
  }
  const tm = advMult(a, d);
  const dtm = damageTakenMult(d, now);
  const varr = between(BT.VAR_LO, BT.VAR_HI, rng);
  if (!T.USE_DMG_V2) {
    const soft2 = 1 - d.def / (d.def + BT.DEF_SOFT);
    let dmg2 = raw * tm * dtm * varr * soft2 * (1 - (d.armor || 0)) * (1 - (d.toughUp || 0));
    out.final = Math.max(1, dmg2);
    if (trace) steps.push({ key: "legacy", name: "\uC61B \uC0B0\uC2DD", mult: raw > 0 ? out.final / raw : 1 });
    return out;
  }
  const dmgType = skill && skill.dmg || damageTypeOf(a);
  const isMag = dmgType === DMG_MAGIC;
  const amp = 1 + ((isMag ? a.magicAmp : a.physAmp) || 0) + (skill && skill.amp || 0);
  const pierce = Math.min(0.9, ((isMag ? a.magicPierce : a.physPierce) || 0) + (skill && skill.pierce || 0));
  const effDef = d.def * (1 - pierce);
  const soft = 1 - effDef / (effDef + BT.DEF_SOFT);
  const res2 = Math.min(T.DMG_RES_CAP, (isMag ? d.magicRes : d.physRes) || 0);
  let dmg = raw * amp * tm * dtm * varr * soft * (1 - res2) * (1 - (d.armor || 0)) * (1 - (d.toughUp || 0));
  if (trace) {
    steps.push({ key: "amp", name: isMag ? "\uB9C8\uBC95 \uC99D\uD3ED" : "\uBB3C\uB9AC \uC99D\uD3ED", mult: amp });
    steps.push({ key: "type", name: "\uC0C1\uC131", mult: tm });
    const rm = raceMult(a, d);
    if (rm !== 1) steps.push({ key: "race", name: "\uC885\uC871 \uC0C1\uC131", mult: rm });
    steps.push({ key: "status", name: "\uC0C1\uD0DC\uC774\uC0C1", mult: dtm });
    steps.push({ key: "var", name: "\uC694\uB3D9", mult: varr });
    steps.push({ key: "def", name: pierce > 0 ? `\uBC29\uC5B4 (\uAD00\uD1B5 ${Math.round(pierce * 100)}%)` : "\uBC29\uC5B4", mult: soft });
    steps.push({ key: "res", name: isMag ? "\uB9C8\uBC95 \uC800\uD56D" : "\uBB3C\uB9AC \uC800\uD56D", mult: 1 - res2 });
    steps.push({ key: "mitigate", name: "\uACBD\uAC10", mult: (1 - (d.armor || 0)) * (1 - (d.toughUp || 0)) });
  }
  const bindAcc = a.statuses && hasStatus(a, "bind", now) ? T.BIND_ACC : 0;
  const dodgeAll = Math.min(FLOW.dodgeUp.cap, (d.dodgeUp || 0) + (d.auraDodgeK || 0));
  const miss = Math.max(0, dodgeAll - ((a.accUp || 0) - bindAcc));
  if (miss > 0 && rng() < miss) {
    out.dodged = true;
    if (trace) steps.push({ key: "dodge", name: "\uD68C\uD53C", mult: 0 });
    return out;
  }
  const bc = d.blockCh || 0;
  if (bc > 0 && rng() < bc) {
    out.blocked = true;
    dmg *= 1 - T.BLOCK_CUT;
    if (trace) steps.push({ key: "block", name: "\uCC28\uB2E8", mult: 1 - T.BLOCK_CUT });
  }
  const cc = Math.max(0, (a.critUp || 0) + (skill && skill.critUp || 0) - (d.critResist || 0));
  if (cc > 0 && rng() < cc) {
    out.crit = true;
    const cm = Math.max(1, T.CRIT_BASE_MULT + (a.critDmg || 0) + (skill && skill.critDmg || 0) - (d.critDmgResist || 0));
    dmg *= cm;
    if (trace) steps.push({ key: "crit", name: "\uCE58\uBA85\uD0C0", mult: cm });
  }
  out.final = Math.max(1, dmg);
  return out;
}

