      if (A2.atkBuff) {
        u.atkUpK = A2.atkBuff * k;
        u.atkUpUntil = until;
      }
      if (A2.defDown) {
        u.defDownK = manaScaledRatio(A2.defDown, u);
        u.defDownUntil = until;
      }
      if (A2.reflect) {
        u.reflectK = manaScaledRatio(A2.reflect, u);
        u.reflectUntil = until;
      }
      if (A2.stealth) {
        u.stealthUntil = this.t + A2.stealth;
        u.ambushK = A2.ambushMult || 1;
      }
      if (A2.critStack) {
        u.critStackK = A2.critStack * k;
        u.critStackUntil = until;
        u.critStackN = 1;
      }
      if (A2.physResBuff || A2.magicResBuff) {
        u.physResBuffK = (A2.physResBuff || 0) * k;
        u.magicResBuffK = (A2.magicResBuff || 0) * k;
        u.resBuffUntil = until;
      }
      if (A2.hpBuff) this.enlarge(u, A2.hpBuff * k, until);
      if (A2.taunt) u.tauntUntil = Math.max(u.tauntUntil || 0, until);
      const grew = !!(A2.hpBuff || A2.physResBuff || A2.magicResBuff);
      if (grew) u.enlargedUntil = until;
      this.emit({ kind: "buff", u, name: u.activeName, taunt: !!A2.taunt, enlarged: grew, stealth: !!A2.stealth });
      this.say(`${u.name} \u2014 ${u.activeName}`);
