var resN = (n) => ({ kind: "res", text: `\uC5F0\uAD6C ${n}\uAC1C \uC644\uB8CC`, goal: n, cur: (s) => (s.lab && s.lab.done || []).length });
var resTier = (t) => ({ kind: "res", text: `${t}\uB2E8 \uC5F0\uAD6C 1\uAC1C \uC644\uB8CC`, goal: 1, cur: (s) => (s.lab && s.lab.done || []).some((id) => !/^squad/.test(id) && +String(id).replace(/^\D+/, "") === t) ? 1 : 0 });
var fac = (id, name, n) => ({ kind: "fac", id, text: `${name} Lv.${n}`, goal: n, cur: (s) => s.fac && s.fac[id] && s.fac[id].lv || 1 });
var job = (j, name) => ({ kind: "job", job: j, text: `${name} \uBC30\uCE58`, goal: 1, cur: (s) => s.estate && s.estate[j] ? 1 : 0 });
var plus = (n) => ({ kind: "plus", text: `\uC7A5\uBE44 \uAC15\uD654 +${n}`, goal: n, cur: (s) => Math.max(0, ...(s.gear || []).map((g) => g.plus || 0)) });
var guild = () => ({ kind: "guild", text: "\uAE38\uB4DC \uAC00\uC785", goal: 1, cur: (s) => s.guild && s.guild.id ? 1 : 0 });
var cnt = (key, n, name) => ({ kind: "cnt", text: `${name} ${n}\uD68C`, goal: n, cnt: key, cur: (s) => s.scenario && s.scenario.n && s.scenario.n[key] || 0 });
