function rollChar(rand = Math.random, state = null, opt = null) {
  return finishChar(rollBody(rand, opt), rand, state);
}
function rollBody(rand = Math.random, opt = null) {
  const mo = opt && (opt.raceId || opt.pool) ? { ...opt.raceId ? { raceId: opt.raceId } : {}, ...opt.pool ? { pool: opt.pool } : {} } : null;
  const ch = mo ? makeChar(rand, mo) : makeChar(rand);
  ensureTaste(ch);
  ch.growthD = growthIndexOf(ch);
  ch.growthStat = growthStatOf(ch);
  if (ch.growthD) {
    for (const k of Object.keys(ch.potential)) {
      ch.potential[k] = Math.max(20, Math.min(98, ch.potential[k] - POT_PER_D * ch.growthD));
    }
  }
  return ch;
}
function finishChar(ch, rand = Math.random, state = null) {
  ch.name = uniqueName(rand, ch.raceId, ensureSex(ch), takenOf(state));
  if (state) issueName(state, ch.name);
  ch.title = randomTitle(rand);
  ch.exp = 0;
  starsOf(ch, rand);
  return ch;
}
